#!/usr/bin/env bash
# Writes infrastructure/argocd/prometheus/values.yaml: the in-cluster Prometheus add-on's values,
# with the same alert and SLO rules as infrastructure/observability/prometheus (one source of
# truth; CI fails when this file is stale). Run after changing either rule file.
set -euo pipefail
cd "$(dirname "$0")/.."
rules=infrastructure/observability/prometheus
out=infrastructure/argocd/prometheus/values.yaml
{
  cat <<'HEADER'
# GENERATED by scripts/prometheus-values.sh from infrastructure/observability/prometheus; do not edit.
#
# Prometheus for the cluster (chart prometheus-community/prometheus), in the `observability`
# namespace the Meridian chart's NetworkPolicies let scrape. Its jobs carry the same names as the
# local Compose setup (`services`, `gateway`), so the alert and SLO rules apply unchanged, and
# label samples with the pod name, which the canary checks (templates/rollouts.yaml) select on.
server:
  retention: 15d
  persistentVolume: { size: 20Gi }
prometheus-pushgateway: { enabled: false }
serverFiles:
  prometheus.yml:
    rule_files: [/etc/config/recording_rules.yml, /etc/config/alerting_rules.yml]
    scrape_configs:
      - job_name: prometheus
        static_configs: [{ targets: ["localhost:9090"] }]
      - job_name: services
        kubernetes_sd_configs: [{ role: pod, namespaces: { names: [meridian] } }]
        relabel_configs:
          - { source_labels: [__meta_kubernetes_pod_annotation_prometheus_io_scrape], regex: "true", action: keep }
          - { source_labels: [__meta_kubernetes_pod_label_app_kubernetes_io_name], regex: gateway, action: drop }
          - { source_labels: [__meta_kubernetes_pod_annotation_prometheus_io_path], regex: (.+), target_label: __metrics_path__ }
          - source_labels: [__address__, __meta_kubernetes_pod_annotation_prometheus_io_port]
            regex: ([^:]+)(?::\d+)?;(\d+)
            replacement: $1:$2
            target_label: __address__
          - { source_labels: [__meta_kubernetes_namespace], target_label: namespace }
          - { source_labels: [__meta_kubernetes_pod_name], target_label: pod }
          - { source_labels: [__meta_kubernetes_pod_label_app_kubernetes_io_name], target_label: app }
      - job_name: gateway
        kubernetes_sd_configs: [{ role: pod, namespaces: { names: [meridian] } }]
        relabel_configs:
          - { source_labels: [__meta_kubernetes_pod_annotation_prometheus_io_scrape], regex: "true", action: keep }
          - { source_labels: [__meta_kubernetes_pod_label_app_kubernetes_io_name], regex: gateway, action: keep }
          - { source_labels: [__meta_kubernetes_pod_annotation_prometheus_io_path], regex: (.+), target_label: __metrics_path__ }
          - source_labels: [__address__, __meta_kubernetes_pod_annotation_prometheus_io_port]
            regex: ([^:]+)(?::\d+)?;(\d+)
            replacement: $1:$2
            target_label: __address__
          - { source_labels: [__meta_kubernetes_namespace], target_label: namespace }
          - { source_labels: [__meta_kubernetes_pod_name], target_label: pod }
HEADER
  echo "  alerting_rules.yml:"
  sed -e 's/^/    /' -e 's/^ *$//' "$rules/alerts.yml"
  echo "  recording_rules.yml:"
  sed -e 's/^/    /' -e 's/^ *$//' "$rules/slo.yml"
} > "$out"
echo "wrote $out"
